import heapq


def _build_intervals(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}

        best_ids = None
        best_value = None
        for chosen in combinations((j for j in jobs if j["id"] not in blocked), k):
            ids = tuple(sorted(j["id"] for j in chosen))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            valid = True
            for time in (j["start"] for j in chosen):
                if sum(j["start"] <= time < j["end"] for j in chosen) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(j["value"] for j in chosen)
            if (best_ids is None or value > best_value or
                (value == best_value and
                 ((tie == "largest" and ids > best_ids) or
                  (tie == "smallest" and ids < best_ids)))):
                best_ids, best_value = ids, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(raw * event.get("tax_bp", 0), mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        features = set(data.get("features", []))
        choices = []
        for name in names:
            rows = packages[name]
            choices.append([None] + [row for row in rows
                if row["version"] not in blocked.get(name, []) and
                (name not in pins or row["version"] == pins[name])])

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: row for name, row in zip(names, assignment) if row is not None}
            if any(name not in selected or not bounds[0] <= selected[name]["version"] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            edges = {name: [] for name in selected}
            valid = True
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if target not in selected or not dep["min"] <= selected[target]["version"] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(selected):
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for target in edges[name]:
                    if not visit(target):
                        return False
                state[name] = 2
                return True
            if not all(visit(name) for name in selected):
                continue

            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in sorted(names, reverse=True))
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"] for name, row in selected.items()}
        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit.get(data["source"], 0)
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, 0)
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupons:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


